window.goarIcon = function(name, size, color, extraClass) {
  var sz = size || 20;
  var col = color ? ('color:' + color + ';') : '';
  var cls = extraClass ? (' class="' + extraClass + '"') : '';
  var entry = window.GOAR_ICON_MAP && window.GOAR_ICON_MAP[name];
  if (entry) {
    return '<svg width="' + sz + '" height="' + sz + '" viewBox="' + entry.vb + '" style="display:inline-block;flex-shrink:0;' + col + '"' + cls + ' aria-hidden="true">' + entry.body + '</svg>';
  }
  var mat = window.GOAR_MATERIAL_ICONS && window.GOAR_MATERIAL_ICONS[name];
  if (mat) {
    return '<svg width="' + sz + '" height="' + sz + '" viewBox="0 0 24 24" style="display:inline-block;flex-shrink:0;' + col + '"' + cls + ' aria-hidden="true">' + mat + '</svg>';
  }
  return '<svg width="' + sz + '" height="' + sz + '" viewBox="0 0 24 24" style="display:inline-block;flex-shrink:0;' + col + '"' + cls + ' aria-hidden="true"><circle cx="12" cy="12" r="7" fill="none" stroke="currentColor" stroke-width="1.8"/></svg>';
};

window.goarSixBarWave = function(size, color) {
  var sz = size || 22;
  var c = color || 'currentColor';
  var bars = [0.24, 0.56, 0.88, 0.46, 0.72, 0.24];
  var parts = '';
  for (var i = 0; i < bars.length; i++) {
    var x = 4 + i * 3.2;
    var hh = bars[i] * 9.2;
    parts += '<line x1="' + x.toFixed(1) + '" y1="' + (12 - hh).toFixed(1) + '" x2="' + x.toFixed(1) + '" y2="' + (12 + hh).toFixed(1) + '" stroke="' + c + '" stroke-width="2.1" stroke-linecap="round"/>';
  }
  return '<svg width="' + sz + '" height="' + sz + '" viewBox="0 0 24 24" style="display:inline-block;flex-shrink:0;" aria-hidden="true">' + parts + '</svg>';
};


